LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    # Validate inputs
    if interval <= 0 or duration <= 0:
        raise ValueError("interval and duration must be greater than zero")

    cpu_data = []
    start_time = time.time()
    system = platform.system()

    while time.time() - start_time < duration:
        timestamp = datetime.now().isoformat()
        cpu_percent = 0

        try:
            if system == "Windows":
                # Windows: use wmic to get CPU load percentage
                result = subprocess.run(
                    ["wmic", "cpu", "get", "loadpercentage"],
                    capture_output=True,
                    text=True,
                    shell=True
                )
                lines = result.stdout.strip().split('\n')
                # Skip header and empty lines
                for line in lines:
                    line = line.strip()
                    if line and line != "LoadPercentage":
                        cpu_percent = int(line)
                        break
            else:
                # Unix/Linux: parse /proc/stat for CPU usage
                try:
                    with open("/proc/stat", "r") as f:
                        line = f.readline()
                        if line.startswith("cpu "):
                            values = list(map(int, line.split()[1:8]))  # user, nice, system, idle, iowait, irq, softirq
                            total = sum(values)
                            idle = values[3] + values[4]  # idle + iowait
                            cpu_percent = round(100 * (total - idle) / total, 2) if total > 0 else 0
                except Exception:
                    # Fallback: try top command
                    result = subprocess.run(
                        ["top", "-bn1"],
                        capture_output=True,
                        text=True,
                        shell=True
                    )
                    for line in result.stdout.split('\n'):
                        if 'Cpu(s)' in line or '%Cpu' in line:
                            parts = line.split(',')
                            for part in parts:
                                if 'id' in part:
                                    try:
                                        idle = float(part.split()[0])
                                        cpu_percent = round(100 - idle, 2)
                                    except:
                                        cpu_percent = 0
                                    break
                            break
        except Exception:
            cpu_percent = 0

        cpu_data.append({
            "timestamp": timestamp,
            "cpu_usage": cpu_percent
        })

        # Sleep for the interval, but check if duration is exceeded
        sleep_time = min(interval, duration - (time.time() - start_time))
        if sleep_time > 0:
            time.sleep(sleep_time)

    # Write data to log file
    try:
        with open(LOGFILE_PATH, 'w') as f:
            json.dump(cpu_data, f, indent=2)
        return LOGFILE_PATH
    except IOError:
        return None

